CustomCss:
body{font-family:'Menlo','Consolas','DejaVu Sans Mono',ui-monospace,monospace;font-size:13px}
h1,h2{font-weight:600}
h2{padding-bottom:8px;border-bottom:1px solid var(--b)}
.form,.sc,.ig,table{border-radius:4px}
.ni{border-left-width:3px}
th{background:var(--s);font-weight:700}
button.bp,button.bd,button.bw{border-radius:4px;font-weight:600}
input,select,textarea{border-radius:4px}
.code,.ip,td.mono{font-weight:600}
